/// An example design: its file in data/examples, its flight configurations (Rocket.getIds()) and
/// its acting motor mounts (MotorMount.isMotorMount(), in the order of the component tree).
struct MotorChooserMountDesignPin
{
    std::string_view design;
    int              configurations;
    int              mounts;
};

/// An acting motor mount of a design: its index among the design's, its component's name, its motor
/// mount diameter (getMotorMountDiameter()) and its length, settled.
struct MotorChooserMountPin
{
    std::string_view design;
    int              mount;
    std::string_view name;
    double           diameter;
    double           length;
};

/// A table the chooser showed: the MD5 of its rows ("<model row>\t<the six column texts>\n" in the
/// view's order, UTF-8) and its model rows in the view's order,
/// kMotorChooserMountRowIndices[firstRow] onwards.
struct MotorChooserMountRowsPin
{
    std::string_view md5;
    int              rows;
    int              firstRow;
};

/// The chooser opened for the mount @p mount in the flight configuration @p configuration (its
/// index in Rocket.getIds()), after setMotorMountAndConfig() and the dialog's open()
/// (selectMotorFromTable()), and what its OK answered. A set is its index in the database's sets
/// (-1 for none), a curve its index in its set (-1 for none).
struct MotorChooserMountOpenPin
{
    std::string_view design;
    int              configuration;
    int              mount;
    /// The mount's motor configuration in the flight configuration: its motor (-1, -1 without one),
    /// ejection delay, the delay's text (ThrustCurveMotor.getDelayString(delay, "Plugged")) and
    /// nozzle exit diameter.
    int              configuredSet;
    int              configuredCurve;
    double           configuredDelay;
    std::string_view configuredDelayText;
    double           configuredNozzle;
    /// The filter panel: the two limit boxes, the thumbs of the diameter and length sliders, the
    /// filter's limits (a diameter limit of none: has... false) and the mount's dimensions label.
    bool             limitDiameter;
    bool             limitLength;
    int              diameterLow;
    int              diameterHigh;
    int              lengthLow;
    int              lengthHigh;
    bool             hasMinimumDiameter;
    double           minimumDiameter;
    bool             hasMaximumDiameter;
    double           maximumDiameter;
    double           minimumLength;
    double           maximumLength;
    std::string_view mountLabel;
    /// "Number of motors:", the table (kMotorChooserMountRows by its MD5) and its selected view row
    /// (-1 for none).
    std::string_view motorsLabel;
    int              rows;
    std::string_view md5;
    int              selectedRow;
    /// The selected motor (getSelectedMotor()).
    int selectedSet;
    int selectedCurve;
    /// The curve list: enabled, the set of its curves (-1 for an empty list), their indices in it,
    /// in its order, joined by ',', and its selected item (-1 for none). The list can show the
    /// curves of another set than the selected one (a configuration without a motor leaves it as it
    /// was).
    bool             curvesEnabled;
    int              curveSet;
    std::string_view curves;
    int              curveIndex;
    /// The delay list's items joined by '|' and its text ("null" for no item selected), the
    /// selected delay, nozzle exit diameter and the nozzle's maximum.
    std::string_view delayItems;
    std::string_view delayText;
    double           delay;
    double           nozzle;
    double           nozzleMaximum;
    /// OK's answer: the motor (-1, -1 for none), the delay and the nozzle exit diameter.
    int    answerSet;
    int    answerCurve;
    double answerDelay;
    double answerNozzle;
};

/// A text typed into the search field at the mount's first open (the open of the same design,
/// configuration and mount): the rows shown.
struct MotorChooserMountSearchPin
{
    std::string_view design;
    int              configuration;
    int              mount;
    std::string_view text;
    int              rows;
    std::string_view md5;
};

/// The node of the preferred curves (PreferredThrustCurveMotors) after a design's opens, its keys
/// sorted.
struct MotorChooserMountPreferredPin
{
    std::string_view design;
    std::string_view digest;
    bool             value;
};

